<?php $pageTitle='Add User';require '../includes/admin-header.php';if($_SERVER['REQUEST_METHOD']==='POST'){try{db()->prepare('INSERT INTO users(full_name,username,email,mobile,password,address,status) VALUES(?,?,?,?,?,?,?)')->execute([trim($_POST['full_name']),trim($_POST['username']),trim($_POST['email']),trim($_POST['mobile']),password_hash($_POST['password'],PASSWORD_DEFAULT),trim($_POST['address']),$_POST['status']]);flash('success','User added.');go('admin/users.php');}catch(PDOException $e){flash('danger','Username, email, or mobile already exists.');}} ?><form method="post" class="card card-body" style="max-width:700px"><div class="row g-3"><div class="col-md-6"><input class="form-control" name="full_name" placeholder="Full name" required></div><div class="col-md-6"><input class="form-control" name="username" placeholder="Username" required></div><div class="col-md-6"><input class="form-control" name="email" type="email" placeholder="Email" required></div><div class="col-md-6"><input class="form-control" name="mobile" placeholder="Mobile" required></div><div class="col-md-6"><input class="form-control" name="password" type="password" placeholder="Password" required></div><div class="col-md-6"><select class="form-select" name="status"><option value="blocked">Blocked</option><option value="active">Active</option></select></div><div class="col-12"><textarea class="form-control" name="address" placeholder="Address"></textarea></div><div><button class="btn btn-dark">Add user</button></div></div></form><?php require '../includes/admin-footer.php'; ?>
